using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.Linq;using Object=UnityEngine.Object;
public static class SetupPickups {
 static Transform Anchor(string n,Transform parent,Vector3 local){var t=new GameObject(n).transform;t.SetParent(parent,false);t.localPosition=local;return t;}
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit Mode required");System.IO.Directory.CreateDirectory("output/Pickups/Backups");var scene=GameObject.Find("Pick up").scene;if(!EditorSceneManager.SaveScene(scene,"output/Pickups/Backups/Gameplay.before-pickups.unity",true))throw new Exception("Backup failed");System.IO.Directory.CreateDirectory("Assets/Models/Pickups/Driveable");AssetDatabase.Refresh();
 foreach(var name in new[]{"Pick up","Pick Up Bigger","Pick Up Last"}){var old=GameObject.Find(name);if(!old||GameObject.Find(name+" - driveable"))throw new Exception("Unexpected pickup state: "+name);bool small=name=="Pick up";var root=new GameObject(name+" - driveable");root.SetActive(false);Undo.RegisterCreatedObjectUndo(root,"Prepare pickup");root.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation*Quaternion.Euler(0,90,0));root.transform.localScale=old.transform.lossyScale;var p=root.transform.position;p.y=Terrain.activeTerrain.SampleHeight(p)+Terrain.activeTerrain.transform.position.y+.02f;root.transform.position=p;
 var model=Object.Instantiate(old,root.transform);model.name="Pickup visuals";model.transform.localPosition=Vector3.zero;model.transform.localRotation=Quaternion.Euler(0,-90,0);model.transform.localScale=Vector3.one;if(PrefabUtility.IsPartOfPrefabInstance(model))PrefabUtility.UnpackPrefabInstance(model,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);foreach(var col in model.GetComponentsInChildren<Collider>())Object.DestroyImmediate(col);
 Transform Find(string suffix)=>model.GetComponentsInChildren<Transform>().First(t=>t.name.EndsWith(suffix));
 Transform Wheel(Transform oldWheel,Transform parent){var a=Anchor(oldWheel.name+" axle",parent,parent.InverseTransformPoint(oldWheel.position));oldWheel.SetParent(a,true);return a;}
 var flOld=Find("Wheel_F.L");var frOld=Find("Wheel_F.R");var rlOld=Find("Wheel_R.L");var rrOld=Find("Wheel_R.R");float radius=flOld.GetComponentInChildren<MeshFilter>().sharedMesh.bounds.extents.y;float wheelbase=Vector3.Distance(root.transform.InverseTransformPoint(flOld.position),root.transform.InverseTransformPoint(rlOld.position));
 var sl=Anchor("Front left steering",root.transform,root.transform.InverseTransformPoint(flOld.position));var sr=Anchor("Front right steering",root.transform,root.transform.InverseTransformPoint(frOld.position));var fl=Wheel(flOld,sl);var fr=Wheel(frOld,sr);var rl=Wheel(rlOld,root.transform);var rr=Wheel(rrOld,root.transform);
 var bounds=new Bounds(Vector3.zero,Vector3.zero);foreach(var f in model.GetComponentsInChildren<MeshFilter>()){var b=f.sharedMesh.bounds;for(int i=0;i<8;i++)bounds.Encapsulate(root.transform.InverseTransformPoint(f.transform.TransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)))));}
 var rig=root.AddComponent<BicycleController>();rig.motorDriven=true;rig.steering=sl;rig.frontWheel=fl;rig.rearWheel=rl;rig.maximumSteeringAngle=28;rig.steeringSmoothTime=.18f;rig.dismountSideDistance=bounds.extents.x*root.transform.lossyScale.x+.8f;rig.dismountLongitudinalDistance=bounds.extents.z*root.transform.lossyScale.z+1;rig.riderView=Anchor("Driver view",root.transform,new Vector3(small?-.49f:-.36f,1.8f,small?.35f:.15f));rig.SetRidingCamera(Vector3.zero,4);rig.cargoLocationName="pickup bed";
 rig.cargoSlots=new[]{Anchor("Bed front left",root.transform,new Vector3(-.45f,small?1.17f:1.38f,-1)),Anchor("Bed front right",root.transform,new Vector3(.45f,small?1.17f:1.38f,-1)),Anchor("Bed rear left",root.transform,new Vector3(-.45f,small?1.17f:1.38f,small?-2.1f:-3)),Anchor("Bed rear right",root.transform,new Vector3(.45f,small?1.17f:1.38f,small?-2.1f:-3))};
 var engine=root.AddComponent<MotorollerController>();using(var so=new SerializedObject(engine)){so.FindProperty("vehicleName").stringValue=name;so.FindProperty("maximumSpeed").floatValue=small?13:11;so.FindProperty("acceleration").floatValue=small?3:2.4f;so.FindProperty("brakingDeceleration").floatValue=8;so.FindProperty("wheelRadius").floatValue=radius;so.FindProperty("wheelbase").floatValue=wheelbase;var center=bounds.center;center.y=(bounds.max.y+.4f)*.5f;var extents=bounds.extents;extents.y=(bounds.max.y-.4f)*.5f;so.FindProperty("collisionCenter").vector3Value=center;so.FindProperty("collisionHalfExtents").vector3Value=extents;so.ApplyModifiedPropertiesWithoutUndo();}engine.Configure();
 var cc=root.GetComponent<CharacterController>();cc.radius=.8f;cc.height=2.15f;cc.center=new Vector3(0,1.10f,0);cc.stepOffset=.18f;cc.skinWidth=.025f;cc.slopeLimit=35;var body=root.AddComponent<BoxCollider>();body.center=bounds.center;body.size=bounds.size;
 var pickup=root.AddComponent<PickupController>();pickup.frontRightSteering=sr;pickup.frontRightWheel=fr;pickup.rearRightWheel=rr;pickup.steeringWheel=Find("Steering_Wheel_LOD0");old.SetActive(false);root.SetActive(true);PrefabUtility.SaveAsPrefabAssetAndConnect(root,"Assets/Models/Pickups/Driveable/"+name.Replace(" ","_")+"_Driveable.prefab",InteractionMode.AutomatedAction);
 }
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);return "Prepared all three pickups, retained original meshes/LODs and original inactive scene references.";
 }}
